    "Mi integración",
  );
  await user.click(screen.getByRole("checkbox", { name: "Leer proyectos" }));
  await user.click(screen.getByRole("button", { name: "Crear" }));
  expect(await screen.findByRole("alert")).toHaveTextContent(
