});
it.each([200, 401])(
  "@s30 does not let a preceding shared read replace a confirmed save: %s",
  async (oldStatus) => {
    let deliver!: (response: Response) => void;
    let confirm!: (response: Response) => void;
    const observer = vi.fn();
    observeAccess(observer);
    const fetcher = vi
      .fn()
      .mockResolvedValueOnce(
        Response.json(
          { ...stored, theme: "LIGHT" },
          { headers: { ETag: tag } },
        ),
      )
      .mockReturnValueOnce(
        new Promise<Response>((resolve) => {
          deliver = resolve;
        }),
      )
      .mockImplementationOnce(() =>
        oldStatus === 401
          ? new Promise<Response>((resolve) => {
              confirm = resolve;
            })
          : Promise.resolve(
              Response.json(stored, {
                headers: { ETag: tag.replace(":0", ":1") },
              }),
            ),
      );
    function SharedConsumer() {
      const { snapshot, reload, save } = useAppearance();
      return (
        <>
          <output>{snapshot?.theme}</output>
          <button
            onClick={() => {
              void reload().catch(() => {});
            }}
          >
            Consultar
          </button>
          <button
            onClick={() => {
              void save({
                theme: "DARK",
                accentLight: stored.accentLight,
                accentDark: stored.accentDark,
              });
            }}
          >
            Guardar
          </button>
        </>
      );
    }
    vi.stubGlobal("fetch", fetcher);
    render(
      <AppearanceProvider>
        <SharedConsumer />
      </AppearanceProvider>,
    );
    await screen.findByText("LIGHT");
    await userEvent.click(screen.getByRole("button", { name: "Consultar" }));
    await userEvent.click(screen.getByRole("button", { name: "Guardar" }));
    if (oldStatus === 401) {
      await act(async () => deliver(new Response(null, { status: 401 })));
      expect(observer).not.toHaveBeenCalled();
      expect(screen.getByRole("status")).toHaveTextContent("LIGHT");
      await act(async () =>
        confirm(
          Response.json(stored, { headers: { ETag: tag.replace(":0", ":1") } }),
        ),
      );
    }
    await screen.findByText("DARK");
    if (oldStatus === 200)
      await act(async () => {
        deliver(
          Response.json(
            { ...stored, theme: "LIGHT" },
            { headers: { ETag: tag } },
          ),
        );
      });
    expect(screen.getByRole("status")).toHaveTextContent("DARK");
    expect(document.documentElement.style.colorScheme).toBe("dark");
    expect(fetcher.mock.calls[1][1].signal.aborted).toBe(true);
    expect(observer).not.toHaveBeenCalled();
  },
);
