    target: { value: "UTC" },
  });
  fireEvent.change(screen.getByLabelText("Lunes · minutos"), {
    target: { value: "35" },
  });
  fireEvent.click(
    screen.getByRole("button", { name: "Guardar disponibilidad" }),
  );
