    .fn()
    .mockImplementation(() =>
      Promise.resolve(Response.json({ items: [], nextCursor: null })),
    );
  vi.stubGlobal("fetch", fetcher);
  render(<App />);
  await screen.findByText("No hay hechos en esta página.");
