it("@s33 expands a closed receipt as plain notes and its own persisted net and work date", async () => {
  const note = "  <script>sin HTML</script>\nsegunda línea  ";
  const close = {
    ...pause,
    action: "CLOSE",
    after: { ...pause.after, status: "closed" },
