it.each(["clean", "uncertain", "pending"])(
  "@s41 refreshes imported appearance preserving prior operation (%s)",
  async (state) => {
    const uncertain = state !== "clean";
    const { preview } = await fileFixture();
    const intent = {
      owner: "Ana",
      requestKey: "00000000-0000-4000-8000-000000000001",
