    expect(screen.getByLabelText(/Descripción/)).toHaveValue(
      "Continuar mañana",
    );
    expect(screen.getByLabelText(/Descripción/)).not.toHaveAttribute(
      "readonly",
    );
    expect(
      screen.getByRole("button", { name: "Crear proyecto" }),
    ).toBeEnabled();
