it("@s2 saves exactly three preferences with revision and session CSRF", async () => {
  const input = {
    theme: "DARK" as const,
    accentLight: "#0000ff",
    accentDark: "#00ffff",
  };
  const value = {
    ...configured,
    accentLight: "#0000FF",
    accentDark: "#00FFFF",
  };
